contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a candidate new owner and a flag indicating
    // whether we should attempt the call as admin. We cannot change msg.sender here,
    // but the contract C was deployed with this InvMutTest as deployer, so InvMutTest is the admin.
    function run(address newOwner, bool doCall) public payable {
        require(true);

        // read owner before
        address ownerBefore = c.owner();

        bool reverted = false;
        bool ret = false;
        if (doCall) {
            // InvMutTest is the admin (it deployed C), so this call should succeed and return true
            try c.setOwner(newOwner) returns (bool ok) {
                ret = ok;
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address ownerAfter = c.owner();

        // General rule:
        // - If we attempted the call and it did not revert, then it returned true and owner changed to newOwner.
        // - If we did not attempt the call or the call reverted, owner stays as before.
        assert(
            // case: attempted and not reverted
            (doCall && !reverted && ret == true && ownerAfter == newOwner)
            // case: not attempted or reverted -> owner unchanged
            || ((!doCall || reverted) && ownerAfter == ownerBefore)
        );
    }

    receive() external payable { }
}

