contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an arbitrary address as input
    function run(address newOwner) public payable {
        require(true);

        // read owner before
        address before = c.owner();

        // attempt to call setOwner and capture whether it reverted and the return value if any
        bool reverted;
        bool returnedTrue;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            returnedTrue = ok;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        address after = c.owner();

        // General rule:
        // - If the call reverted then owner is unchanged (after == before).
        // - If the call succeeded then it returned true and owner was set to newOwner.
        assert((reverted && after == before) || (!reverted && returnedTrue && after == newOwner));
    }

    receive() external payable {}
